// The expected information of the Poisson-inverse Gaussian, family pig1 (mu, sigma), and its first and
// second derivatives on the parameter scale, from the partials of S = E_sigma_sigma. Generated by
// misure_open5/p6_pig_fast/gen_pig1.py; same construction as assemble3() and assemble4() of
// pt_pig1_d34e_map.h:
//   E_ss = S,  E_ms = R1 S,  E_mm = N + R2 S,  R1 = -sigma^2 u,  R2 = sigma^4 u^2,  N = -u / mu,
//   u = 1 / (1 + sigma mu),
// so that the derivatives of E_ms and E_mm are Leibniz sums of the partials of S (layout of series_S:
// s[k (k + 1) / 2 + q] = d^k S / dmu^(k-q) dsigma^q) and the exact derivatives of R1, R2 and N, written
// in factored form (numerators with terms of one sign). assemble0 fills o[p] (p = mm, ss, ms);
// assemble1 fills o[2 p + c] (c = mu, sigma); assemble2 fills o[3 p + t] (t = (mu,mu), (sigma,sigma),
// (mu,sigma)): the layouts of dexpected_names() and d2expected_names().
#ifndef DISTRIBUTIONS7_PT_PIG1_EXPECTED_FAST_H
#define DISTRIBUTIONS7_PT_PIG1_EXPECTED_FAST_H

#include <cmath>
#include "pt_pig1_d34e_map.h"
#include "pt_pig1_d34e_asym.h"
#include "pt_pig1_fixsig.h"

namespace pig_map {

static inline void assemble0(const double mu, const double sg, const double* s, double* o) {
    const double u = 1.0 / (1.0 + sg * mu);
    const double mi = 1.0 / mu;
    const double s00 = s[0];
    const double r100 = -sg*sg*u;
    const double r200 = sg*sg*sg*sg*u*u;
    const double n00 = -u*mi;
    o[0] = r200 * s00 + n00;
    o[1] = s00;
    o[2] = r100 * s00;
}

static inline void assemble1(const double mu, const double sg, const double* s, double* o) {
    const double u = 1.0 / (1.0 + sg * mu);
    const double mi = 1.0 / mu;
    const double s00 = s[0];
    const double s10 = s[1];
    const double s01 = s[2];
    const double r100 = -sg*sg*u;
    const double r101 = -sg*(2.0 + mu*sg)*u*u;
    const double r110 = sg*sg*sg*u*u;
    const double r200 = sg*sg*sg*sg*u*u;
    const double r201 = 2.0*sg*sg*sg*(2.0 + mu*sg)*u*u*u;
    const double r210 = -2.0*sg*sg*sg*sg*sg*u*u*u;
    const double n00 = -u*mi;
    const double n01 = u*u;
    const double n10 = (1.0 + 2.0*mu*sg)*u*u*mi*mi;
    o[0] = r200 * s10 + r210 * s00 + n10;
    o[1] = r200 * s01 + r201 * s00 + n01;
    o[2] = s10;
    o[3] = s01;
    o[4] = r100 * s10 + r110 * s00;
    o[5] = r100 * s01 + r101 * s00;
}

static inline void assemble2(const double mu, const double sg, const double* s, double* o) {
    const double u = 1.0 / (1.0 + sg * mu);
    const double mi = 1.0 / mu;
    const double s00 = s[0];
    const double s10 = s[1];
    const double s01 = s[2];
    const double s20 = s[3];
    const double s11 = s[4];
    const double s02 = s[5];
    const double r100 = -sg*sg*u;
    const double r101 = -sg*(2.0 + mu*sg)*u*u;
    const double r102 = -2.0*u*u*u;
    const double r110 = sg*sg*sg*u*u;
    const double r111 = sg*sg*(3.0 + mu*sg)*u*u*u;
    const double r120 = -2.0*sg*sg*sg*sg*u*u*u;
    const double r200 = sg*sg*sg*sg*u*u;
    const double r201 = 2.0*sg*sg*sg*(2.0 + mu*sg)*u*u*u;
    const double r202 = 2.0*sg*sg*(6.0 + mu*mu*sg*sg + 4.0*mu*sg)*u*u*u*u;
    const double r210 = -2.0*sg*sg*sg*sg*sg*u*u*u;
    const double r211 = -2.0*sg*sg*sg*sg*(5.0 + 2.0*mu*sg)*u*u*u*u;
    const double r220 = 6.0*sg*sg*sg*sg*sg*sg*u*u*u*u;
    const double n00 = -u*mi;
    const double n01 = u*u;
    const double n02 = -2.0*mu*u*u*u;
    const double n10 = (1.0 + 2.0*mu*sg)*u*u*mi*mi;
    const double n11 = -2.0*sg*u*u*u;
    const double n20 = -2.0*(1.0 + 3.0*mu*sg + 3.0*mu*mu*sg*sg)*u*u*u*mi*mi*mi;
    o[0] = r200 * s20 + 2.0 * r210 * s10 + r220 * s00 + n20;
    o[1] = r200 * s02 + 2.0 * r201 * s01 + r202 * s00 + n02;
    o[2] = r200 * s11 + r201 * s10 + r210 * s01 + r211 * s00 + n11;
    o[3] = s20;
    o[4] = s02;
    o[5] = s11;
    o[6] = r100 * s20 + 2.0 * r110 * s10 + r120 * s00;
    o[7] = r100 * s02 + 2.0 * r101 * s01 + r102 * s00;
    o[8] = r100 * s11 + r101 * s10 + r110 * s01 + r111 * s00;
}

// The expected information (ORDER 0, o[3]), its first derivatives (ORDER 1, o[6]) or its second
// derivatives (ORDER 2, o[9]) in the layouts above, from the partials of S of orders 0 to ORDER in the
// regions where S does not need a sum over the support: the series in sigma (series_region), the
// expansion in 1/mu at fixed sigma mu (asym_region), the two regions of src/d34e_pig1.cpp, and the
// expansion in 1/mu at fixed sigma (fixsig_S of pt_pig1_fixsig.h), which accepts or declines point by
// point. Returns false elsewhere; the caller then sums over the support.
template <int ORDER>
static inline bool pig1_expected_fast(const double mu, const double sg, double* o) {
    double s[6];
    if (series_region(mu, sg)) {
        series_S(mu, sg, ORDER, s);
    } else if (asym_region(mu, sg)) {
        asym_S(mu, sg, ORDER, s);
    } else if (!fixsig_S(mu, sg, ORDER, s)) {
        return false;
    }
    if constexpr (ORDER == 0) assemble0(mu, sg, s, o);
    else if constexpr (ORDER == 1) assemble1(mu, sg, s, o);
    else assemble2(mu, sg, s, o);
    return true;
}

}  // namespace pig_map

#endif
